import { clamp } from '../bam.js';
export const EYE_WIDTH=96,EYE_HEIGHT=64;
const blankBlob=()=>({count:0,x:0,y:0,minX:Infinity,maxX:-Infinity,minY:Infinity,maxY:-Infinity});
