          const i=(y+py)*w+x+px,gx=(old[i+1]-old[i-1])/2,gy=(old[i+w]-old[i-w])/2,t=gray[i]-old[i];
          xx+=gx*gx;xy+=gx*gy;yy+=gy*gy;xt+=gx*t;yt+=gy*t;energy+=t*t;on+=Math.max(0,t);off+=Math.max(0,-t);
        }
